-- Cava de Quesos Bocanegra. Fuente: cavabocanegra.com; pin: OSM
INSERT INTO places (id, name, category, subcategory, latitude, longitude, address, short_description, full_description, price_range, image_urls, thumbnail_url, phone_number, email, website, whatsapp_number, schedule_json, amenities, tags, content_verified)
VALUES ('ae31efd3-81cc-5ac7-92b5-66e8172ea106', $v$Cava de Quesos Bocanegra$v$, 'experiencias', $v$Quesería$v$, 20.5458340, -99.9521380, $v$Carretera Estatal 200 km 50, Fuentezuelas, Tequisquiapan$v$, $v$La primera cava de quesos de Tequis$v$, $v$Cava subterránea donde maduran quesos de autor de receta europea, de la marca NéOle. La Visita a la Cava dura 40 minutos y sale cada hora, de 10 a 16 h, todos los días; conviene reservar. También tiene restaurante.$v$, 'moderate', ARRAY[$v$https://panel.tequismagico.com/uploads/lugares/cava-bocanegra-cava.jpg$v$, $v$https://panel.tequismagico.com/uploads/lugares/cava-bocanegra-estantes.jpg$v$, $v$https://panel.tequismagico.com/uploads/lugares/cava-bocanegra-queso.jpg$v$, $v$https://panel.tequismagico.com/uploads/lugares/cava-bocanegra-terraza.jpg$v$]::text[], $v$https://panel.tequismagico.com/uploads/lugares/cava-bocanegra-cava.jpg$v$, $v$414-273-3369$v$, NULL, $v$https://www.cavabocanegra.com/$v$, NULL, $v${"lunes": "10:00–18:00", "martes": "10:00–17:00", "miércoles": "10:00–18:00", "jueves": "10:00–18:00", "viernes": "10:00–19:00", "sábado": "10:00–19:00", "domingo": "9:00–19:00"}$v$::jsonb, ARRAY[$v$Degustaciones$v$, $v$Restaurante$v$, $v$Reservaciones$v$]::text[], ARRAY[$v$Quesos$v$, $v$Cata$v$, $v$Artesanal$v$]::text[], true);

-- Finca VAI. Fuente: quesosvai.com; pin: OSM
INSERT INTO places (id, name, category, subcategory, latitude, longitude, address, short_description, full_description, price_range, image_urls, thumbnail_url, phone_number, email, website, whatsapp_number, schedule_json, amenities, tags, content_verified)
VALUES ('eba5f710-5769-5afa-b66c-80006c114be2', $v$Finca VAI$v$, 'experiencias', $v$Quesería$v$, 20.5976610, -100.1229000, $v$Km 30 carretera libre Querétaro–Tequisquiapan, Purísima de Cubos, Colón$v$, $v$Rancho quesero familiar con recorrido$v$, $v$Rancho quesero con historia familiar desde los años 1920. El Recorrido del queso incluye ganadería, fábrica, sótano de maduración y degustación guiada. No hace falta reservar en grupos pequeños; con más de 10 personas, sí. Está a media hora de Tequis, ya en el municipio de Colón.$v$, 'budget', ARRAY[$v$https://panel.tequismagico.com/uploads/lugares/finca-vai-rancho.jpg$v$, $v$https://panel.tequismagico.com/uploads/lugares/finca-vai-sotano.jpg$v$]::text[], $v$https://panel.tequismagico.com/uploads/lugares/finca-vai-rancho.jpg$v$, $v$414-226-4353$v$, NULL, $v$https://www.quesosvai.com/$v$, $v$414-226-4353$v$, $v${"lunes": "10:00–16:00", "martes": "10:00–16:00", "miércoles": "10:00–16:00", "jueves": "10:00–16:00", "viernes": "10:00–16:00", "sábado": "10:00–17:00", "domingo": "10:00–17:00"}$v$::jsonb, ARRAY[$v$Degustaciones$v$, $v$Tours$v$]::text[], ARRAY[$v$Quesos$v$, $v$Artesanal$v$]::text[], true);

