VALUES ('d020202d-8a87-58a6-b976-1d667512b13a', $v$Bodegas De Cote$v$, 'experiencias', $v$Viñedo$v$, 20.6965710, -99.8803350, $v$Libramiento Norponiente km 5.9, Tunas Blancas, Ezequiel Montes$v$, $v$Casa vitivinícola en el Valle de Bernal$v$, $v$Viñedo de más de 50 hectáreas y 21 variedades. Ofrece recorridos a pie, en bici y en tren, cata, Gran Reserva y pisado de uva. No publica precios: pregunta al reservar.$v$, 'moderate', ARRAY[$v$https://panel.tequismagico.com/uploads/lugares/de-cote-vista-aerea.jpg$v$, $v$https://panel.tequismagico.com/uploads/lugares/de-cote-barricas.jpg$v$]::text[], $v$https://panel.tequismagico.com/uploads/lugares/de-cote-vista-aerea.jpg$v$, $v$441-277-5000$v$, $v$reservaciones@decote.mx$v$, $v$https://decote.mx$v$, NULL, $v${"lunes": "11:00–17:00", "martes": "11:00–17:00", "miércoles": "11:00–17:00", "jueves": "11:00–17:00", "viernes": "11:00–17:00", "sábado": "11:00–17:00", "domingo": "11:00–17:00"}$v$::jsonb, ARRAY[$v$Tours$v$, $v$Cata$v$, $v$Reservaciones$v$]::text[], ARRAY[$v$Vino$v$, $v$Tours$v$]::text[], true);

